local _, addon = ...

addon.localeData.enUS.Blessings = {MIGHT={name="Blessing of Might",ziel={"May the Light grant you strength, %s.","*places a steady hand on %s's shoulder and speaks a blessing of strength.*"},gruppe={"May the Light strengthen our ranks."}},WISDOM={name="Blessing of Wisdom",ziel={"May the Light sharpen your mind, %s.","*raises a hand over %s in a calm blessing of wisdom.*"},gruppe={"May the Light grant us wisdom."}},PROTECTION={name="Blessing of Protection",ziel={"May the Light guard you from harm, %s.","*draws a protective sign of Light before %s.*"},gruppe={"May the Light watch over us."}},SALVATION={name="Blessing of Salvation",ziel={"May our enemies' wrath pass you by, %s.","*makes a restrained gesture over %s, asking the Light to turn hostile eyes away.*"},gruppe={"May hostile eyes pass us by."}},FREEDOM={name="Blessing of Freedom",ziel={"May the Light break your bonds, %s.","*cuts a bright sign through the air before %s as unseen bonds fall away.*"},gruppe={"No chain shall hold us."}},KINGS={name="Blessing of Kings",ziel={"May the blessing of kings rest upon you, %s.","*stands tall and marks %s with a solemn sign of the Light.*"},gruppe={"May the blessing of kings rest upon us all."}}}
